#!/usr/bin/env python3

# This script reads the CSV files generated by the legendre_stability.c program, 
# extracts the computed Legendre polynomial values and their signed/relative errors,
# and creates plots comparing the forward and backward Miller methods to the GSL reference values. 
# The first plot shows the computed P_l(x) values for each method, while the second,
# third, and fourth plots show the signed error, signed relative error, and
# absolute relative error magnitude.
# The generated plots are saved as PNG files in the "plots_python" directory, 
# with filenames corresponding to the input CSV files. 

# Usage: python plot_legendre.py
# Note: Run the legendre_stability.c program first to generate the CSV files before executing this plotting script.
# The script assumes that the CSV files are named in the format "legendre_x_*.csv" and are located in the same directory as the script.

import csv
from pathlib import Path

import matplotlib.pyplot as plt
from matplotlib.ticker import MaxNLocator


# Extracts the x value from the filename stem by removing the "legendre_x_" prefix and replacing "m" with "-" and "p" with ".".
def x_label_from_stem(stem: str) -> str:
    prefix = "legendre_x_"
    tag = stem[len(prefix):] if stem.startswith(prefix) else stem
    return tag.replace("m", "-").replace("p", ".")


def symmetric_limits(values, margin=1.125, fallback=1.0):
    max_abs = max((abs(value) for value in values), default=0.0)
    if max_abs == 0.0:
        max_abs = fallback
    bound = margin * max_abs
    return -bound, bound


# Reads a CSV file containing Legendre polynomial values and their signed/relative errors,
# and returns a dictionary with the data organized by columns.
def read_csv(path: Path):
    columns = {
        "l": [],
        "forward_double": [],
        "backward_miller": [],
        "reference_quad": [],
        "reference_gsl": [],
        "err_forward": [],
        "err_backward": [],
        "rel_err_forward": [],
        "rel_err_backward": [],
    }

    with path.open(newline="", encoding="utf-8") as handle:
        reader = csv.DictReader(handle)
        for row in reader:
            columns["l"].append(int(row["l"]))
            columns["forward_double"].append(float(row["forward_double"]))
            columns["backward_miller"].append(float(row["backward_miller"]))
            columns["reference_quad"].append(float(row["reference_quad"]))
            columns["reference_gsl"].append(float(row["reference_gsl"]))
            columns["err_forward"].append(float(row["err_forward"]))
            columns["err_backward"].append(float(row["err_backward"]))
            columns["rel_err_forward"].append(float(row["rel_err_forward"]))
            columns["rel_err_backward"].append(float(row["rel_err_backward"]))

    return columns

# Generates plots comparing the forward and backward Miller methods to the quad reference values for Legendre polynomials,
# as well as the signed and relative errors for each method.
# The plots are saved as PNG files in the specified output directory, with filenames corresponding to the input CSV files.
def make_plot(csv_path: Path, output_dir: Path):
    data = read_csv(csv_path)
    output_path = output_dir / f"{csv_path.stem}.png"
    x_label = x_label_from_stem(csv_path.stem)
    abs_rel_forward = [abs(value) if value == value else float("nan") for value in data["rel_err_forward"]]
    abs_rel_backward = [abs(value) if value == value else float("nan") for value in data["rel_err_backward"]]
    abs_rel_values = [value for value in abs_rel_forward + abs_rel_backward if value == value and value > 0.0]

    # Define consistent colors
    forward_color = 'blue'
    backward_color = 'red'
    reference_color = 'gray'

    fig, axes = plt.subplots(3, 1, figsize=(14, 15), constrained_layout=True)
    # fig, axes = plt.subplots(4, 1, figsize=(14, 15), constrained_layout=True)
    fig.suptitle(f"Legendre Polynomial Comparison for x={x_label}", fontsize=16)

    # axes[0].plot(data["l"], data["reference_quad"], linewidth=4, label="Reference quad")
    axes[0].plot(data["l"], data["reference_gsl"], linewidth=5, color=reference_color, label="Reference gsl")
    axes[0].plot(data["l"], data["forward_double"], marker="o", markersize=3, linewidth=2, color=forward_color, label="Forward double")
    axes[0].plot(
        data["l"], data["backward_miller"], marker="s", markersize=3, linewidth=2, color=backward_color, label="Backward Miller"
    )
    axes[0].set_xlabel("Degree l", fontsize=13, labelpad=10)
    axes[0].set_ylabel(r"Legendre Polynomial $P_\ell(x)$", fontsize=13, labelpad=12)
    axes[0].grid(True, alpha=0.3)
    axes[0].legend()
    axes[0].tick_params(axis="both", labelsize=11)
    axes[0].xaxis.set_major_locator(MaxNLocator(nbins=12, integer=True))

    axes[1].plot(data["l"], data["err_forward"], marker="o", markersize=3, linewidth=2, color=forward_color, label="Forward error")
    axes[1].plot(data["l"], data["err_backward"], marker="s", markersize=3, linewidth=2, color=backward_color, label="Backward error")
    axes[1].set_xlabel("Degree l", fontsize=13, labelpad=10)
    axes[1].set_ylabel("Signed error", fontsize=13, labelpad=12)
    axes[1].axhline(0.0, color="black", linewidth=1.0, alpha=0.6)
    axes[1].grid(True, alpha=0.3)
    axes[1].legend()
    axes[1].tick_params(axis="both", labelsize=11)
    axes[1].xaxis.set_major_locator(MaxNLocator(nbins=12, integer=True))
    axes[1].set_ylim(*symmetric_limits(data["err_forward"] + data["err_backward"]))

    axes[2].plot(
        data["l"], data["rel_err_forward"], marker="o", markersize=3, linewidth=2, color=forward_color, label="Forward rel. error"
    )
    axes[2].plot(
        data["l"], data["rel_err_backward"], marker="s", markersize=3, linewidth=2, color=backward_color, label="Backward rel. error"
    )
    axes[2].set_xlabel("Degree l", fontsize=13, labelpad=10)
    axes[2].set_ylabel("Signed relative error", fontsize=13, labelpad=12)
    axes[2].axhline(0.0, color="black", linewidth=1.0, alpha=0.6)
    axes[2].grid(True, alpha=0.3)
    axes[2].legend()
    axes[2].tick_params(axis="both", labelsize=11)
    axes[2].xaxis.set_major_locator(MaxNLocator(nbins=12, integer=True))
    rel_values = [value for value in data["rel_err_forward"] + data["rel_err_backward"] if value == value]
    axes[2].set_ylim(*symmetric_limits(rel_values))

    # axes[3].plot(
    #     data["l"], abs_rel_forward, marker="o", markersize=3, linewidth=2, label="|Forward rel. error|"
    # )
    # axes[3].plot(
    #     data["l"], abs_rel_backward, marker="s", markersize=3, linewidth=2, label="|Backward rel. error|"
    # )
    # axes[3].set_xlabel("Degree l", fontsize=13, labelpad=10)
    # axes[3].set_ylabel("Absolute relative error", fontsize=13, labelpad=12)
    # axes[3].set_yscale("log")
    # axes[3].grid(True, which="both", alpha=0.3)
    # axes[3].legend()
    # axes[3].tick_params(axis="both", labelsize=11)
    # axes[3].xaxis.set_major_locator(MaxNLocator(nbins=12, integer=True))
    # if abs_rel_values:
    #     ymin = min(abs_rel_values)
    #     ymax = max(abs_rel_values)
    #     # axes[3].set_ylim(max(1.0e-18, ymin / 10.0), ymax * 10.0)
    #     axes[3].set_ylim(ymin / 100.0, ymax * 100.0)

    fig.savefig(output_path, dpi=150)
    plt.close(fig)


def main():
    root = Path(".")
    output_dir = root / "plots_python"
    output_dir.mkdir(exist_ok=True)

    csv_files = sorted(root.glob("legendre_x_*.csv"))
    if not csv_files:
        raise SystemExit("No CSV files found. Run the solver first.")

    for csv_path in csv_files:
        make_plot(csv_path, output_dir)


if __name__ == "__main__":
    main()
